export interface ConnectorConfig {
  /** Datadog API key (sent as DD-API-KEY header) */
  datadogApiKey: string;
  /** Datadog Application key (sent as DD-APPLICATION-KEY header) */
  datadogAppKey: string;
  /** Datadog site domain, e.g. "datadoghq.com", "us3.datadoghq.com", "datadoghq.eu" */
  datadogSite: string;
  /** Optional fetch implementation for testing or customization */
  fetch?: typeof fetch;
}

export interface MailchimpResponse {
  /** Final HTTP status after retries (e.g., 200, 429) */
  status: number;
  /** Response headers (case-insensitive) */
  headers: Record<string, string>;
  /** Total time spent across all attempts in milliseconds */
  elapsedTime: number;
  /** JSON body of the final response */
  body: unknown;
}

export interface MailchimpRateLimitPayload {
  /** Final response after retry loop completes (optional; defaults used if omitted) */
  response?: MailchimpResponse;
  /** Original request context for enrichment (optional) */
  request?: {
    method: string;
    url: string;
    body?: unknown;
    headers?: Record<string, string>;
  };
}

export interface HandleResult {
  /** Datadog event ID */
  eventId: string;
  /** Datadog event URL */
  eventUrl: string;
}

/**
 * Creates a Datadog event recording the outcome of a Mailchimp API rate-limit (HTTP 429) incident.
 * The payload should contain the final response after any external retry logic has completed.
 * If `payload.response` is omitted, a generic event with default values is created.
 */
export async function handle(
  payload: MailchimpRateLimitPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required config
  if (!config.datadogApiKey) {
    throw new Error('Missing required config: datadogApiKey (env DATADOG_API_KEY)');
  }
  if (!config.datadogAppKey) {
    throw new Error('Missing required config: datadogAppKey (env DATADOG_APP_KEY)');
  }
  if (!config.datadogSite) {
    throw new Error('Missing required config: datadogSite (env DATADOG_SITE)');
  }

  const fetchImpl = config.fetch ?? fetch;

  // Extract response data with defaults
  const response = payload.response;
  const finalStatus = response?.status ?? 429;
  const headers = response?.headers ?? {};
  // Retry-After header is case-insensitive
  const retryAfterHeader = headers['retry-after'] ?? headers['Retry-After'] ?? 'undefined';
  const durationMs = response?.elapsedTime ?? 0;
  const errorDetails = response?.body;

  // Build Datadog event payload per documented example
  const title = 'Mailchimp API Rate Limit Exceeded';
  const text = `Mailchimp API request failed after 3 retries due to rate limiting. Final status: ${finalStatus}, Duration: ${durationMs}ms, Retry-After header: ${retryAfterHeader}`;
  const tags = ['source:mailchimp', 'type:rate_limit', `status:${finalStatus}`];
  const alertType = 'error';
  const priority = 'normal';
  const sourceTypeName = 'mailchimp_rate_limit';

  const eventBody = {
    title,
    text,
    tags,
    alert_type: alertType,
    priority,
    source_type_name: sourceTypeName,
  };

  const url = `https://event-management-intake.${config.datadogSite}/api/v2/events`;

  const res = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'DD-API-KEY': config.datadogApiKey,
      'DD-APPLICATION-KEY': config.datadogAppKey,
    },
    body: JSON.stringify(eventBody),
  });

  if (!res.ok) {
    const errorText = await res.text().catch(() => '');
    throw new Error(`Datadog Events API error: ${res.status} ${res.statusText} at ${url} - ${errorText}`);
  }

  const result = (await res.json()) as { id: string; url: string };
  return {
    eventId: result.id,
    eventUrl: result.url,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, MailchimpRateLimitPayload, MailchimpResponse } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const result = await handle(SOURCE_EXAMPLE as unknown as MailchimpRateLimitPayload, {
      datadogApiKey: 'test-api-key',
      datadogAppKey: 'test-app-key',
      datadogSite: 'datadoghq.com',
      fetch,
    });
    expect(calls.length).toBeGreaterThan(0);
    expect(result.eventId).toBe('event-id-123');
    expect(result.eventUrl).toBe('https://app.datadoghq.com/event/jump?event_id=event-id-123');
    // Verify request shape
    const call = calls[0];
    expect(call.method).toBe('POST');
    expect(call.url).toMatch(/^https:\/\/event-management-intake\.datadoghq\.com\/api\/v2\/events$/);
    expect(call.headers.get('dd-api-key')).toBe('test-api-key');
    expect(call.headers.get('dd-application-key')).toBe('test-app-key');
    const body = call.json as Record<string, unknown>;
    expect(body.title).toBe('Mailchimp API Rate Limit Exceeded');
    expect(body.tags).toEqual(['source:mailchimp', 'type:rate_limit', 'status:429']);
    expect(body.alert_type).toBe('error');
    expect(body.priority).toBe('normal');
    expect(body.source_type_name).toBe('mailchimp_rate_limit');
  });
});

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    datadogApiKey: 'test-api-key',
    datadogAppKey: 'test-app-key',
    datadogSite: 'datadoghq.com',
  };

  it('happy path: creates event with full response payload', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.endsWith('/api/v2/events') ? jsonResponse({ id: 'evt-456', url: 'https://app.datadoghq.com/event/jump?event_id=evt-456' }, 201) : jsonResponse({ error: 'not found' }, 404)
    );

    const payload: MailchimpRateLimitPayload = {
      response: {
        status: 429,
        headers: { 'retry-after': '5', 'content-type': 'application/json' },
        elapsedTime: 1200,
        body: { type: 'rate_limit', title: 'Too Many Requests', status: 429, detail: 'Exceeded 10 simultaneous connections', instance: 'abc123' },
      },
      request: { method: 'POST', url: 'https://us1.api.mailchimp.com/3.0/campaigns', body: { name: 'test' } },
    };

    const result = await handle(payload, { ...baseConfig, fetch });

    expect(result.eventId).toBe('evt-456');
    expect(result.eventUrl).toBe('https://app.datadoghq.com/event/jump?event_id=evt-456');
    expect(calls.length).toBe(1);

    const call = calls[0];
    const body = call.json as Record<string, unknown>;
    expect(body.title).toBe('Mailchimp API Rate Limit Exceeded');
    expect(body.text).toBe('Mailchimp API request failed after 3 retries due to rate limiting. Final status: 429, Duration: 1200ms, Retry-After header: 5');
    expect(body.tags).toEqual(['source:mailchimp', 'type:rate_limit', 'status:429']);
  });

  it('auth mechanism: sends DD-API-KEY and DD-APPLICATION-KEY headers', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.endsWith('/api/v2/events') ? jsonResponse({ id: 'evt-789', url: 'https://app.datadoghq.com/event/jump?event_id=evt-789' }, 201) : jsonResponse({ error: 'not found' }, 404)
    );

    await handle({}, { ...baseConfig, fetch });

    const call = calls[0];
    expect(call.headers.get('dd-api-key')).toBe('test-api-key');
    expect(call.headers.get('dd-application-key')).toBe('test-app-key');
    expect(call.headers.get('content-type')).toBe('application/json');
  });

  it('field mapping: maps response fields to event text and tags', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.endsWith('/api/v2/events') ? jsonResponse({ id: 'evt-111', url: 'https://app.datadoghq.com/event/jump?event_id=evt-111' }, 201) : jsonResponse({ error: 'not found' }, 404)
    );

    const payload: MailchimpRateLimitPayload = {
      response: {
        status: 200,
        headers: { 'Retry-After': '10' },
        elapsedTime: 3500,
        body: { success: true },
      },
    };

    await handle(payload, { ...baseConfig, fetch });

    const body = calls[0].json as Record<string, unknown>;
    expect(body.text).toBe('Mailchimp API request failed after 3 retries due to rate limiting. Final status: 200, Duration: 3500ms, Retry-After header: 10');
