    const { fetch, calls } = fakeFetch((req) =>
      req.url.endsWith('/api/v2/events') ? jsonResponse({ errors: ['invalid api key'] }, 401) : jsonResponse({ error: 'not found' }, 404)
    );

    await expect(handle({}, { ...baseConfig, fetch })).rejects.toThrow('Datadog Events API error: 401 Unauthorized at https://event-management-intake.datadoghq.com/api/v2/events');
