    const { fetch, calls } = fakeFetch((req) =>
      req.url.includes('us3.datadoghq.com') ? jsonResponse({ id: 'evt-222', url: 'https://app.datadoghq.com/event/jump?event_id=evt-222' }, 201) : jsonResponse({ error: 'not found' }, 404)
