    const { fetch, calls } = fakeFetch((req) =>
      req.url.endsWith('/api/v2/events') ? jsonResponse({ id: 'evt-444', url: 'https://app.datadoghq.com/event/jump?event_id=evt-444' }, 201) : jsonResponse({ error: 'not found' }, 404)
    );

    const payload: MailchimpRateLimitPayload = {
      response: {
        status: 429,
        headers: { 'Retry-After': '30' }, // capitalized
        elapsedTime: 500,
        body: {},
      },
    };

    await handle(payload, { ...baseConfig, fetch });

    const body = calls[0].json as Record<string, unknown>;
    expect(body.text).toContain('Retry-After header: 30');
  });
});

